// Registrations since the last run, in UTC as Weezevent compares them, with a one-hour overlap;
// the next node skips the participants already handled. The day before on the first run.
const memory = $getWorkflowStaticData('global');
const now = $now.toUTC();
const from = memory.lastRun ? DateTime.fromMillis(memory.lastRun).toUTC().minus({ hours: 1 }) : now.minus({ days: 1 });
return [{ json: { since: from.toFormat('yyyy-MM-dd HH:mm:ss'), sinceMillis: from.toMillis(), runStart: now.toMillis() } }];

// Remember this run, then output the participants not handled yet. A participant is forgotten
// a day after the start of the fetched period: no answer can return it any more.
const memory = $getWorkflowStaticData('global');
const { runStart, sinceMillis } = $('Since last check').first().json;
const participants = $input.first().json.body || [];
const seen = memory.seen || {};
for (const [id, at] of Object.entries(seen)) if (at < sinceMillis - 24 * 3600 * 1000) delete seen[id];
const fresh = participants.filter((participant) => !seen[participant.id_participant]);
for (const participant of fresh) seen[participant.id_participant] = runStart;
memory.seen = seen;
memory.lastRun = runStart;
return fresh.map((participant) => ({ json: participant }));

// The phone number, if the registration form asks for it, in international format.
const form = $json.form || {};
const field = Object.keys(form).find((name) => /t[ée]l[ée]phone|portable|mobile|phone/i.test(name));
let phone = String((field && form[field]) || '').replace(/[\s.()-]/g, '');
if (/^00\d+$/.test(phone)) phone = '+' + phone.slice(2);
if (/^\+330\d{9}$/.test(phone)) phone = '+33' + phone.slice(4);
if (/^0[1-9]\d{8}$/.test(phone)) phone = '+33' + phone.slice(1);
return {
	json: {
		firstName: $json.prenom || '',
		lastName: $json.nom || '',
		email: $json.email || '',
		phone,
	},
};
